package com.cloudcart.service;
import com.cloudcart.entity.Entities.*;import com.cloudcart.repository.UserRepository;import com.cloudcart.repository.ProductRepository;import com.cloudcart.repository.CartRepository;import com.cloudcart.repository.OrderRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.math.BigDecimal;import java.util.*;
@Service public class CloudCartService {public final UserRepository users;public final ProductRepository products;public final CartRepository carts;public final OrderRepository orders;public CloudCartService(UserRepository u,ProductRepository p,CartRepository c,OrderRepository o){users=u;products=p;carts=c;orders=o;}public User current(String email){return users.findByEmail(email).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));}public Cart cart(User u){return carts.findByUserId(u.id).orElseGet(()->{Cart c=new Cart();c.user=u;return carts.save(c);});}public Map<String,Object> cartView(Cart c){List<Map<String,Object>> items=c.items.stream().<Map<String,Object>>map(i->{var m=new LinkedHashMap<String,Object>();m.put("id",i.id);m.put("productId",i.product.id);m.put("name",i.product.name);m.put("category",i.product.category);m.put("imageUrl",i.product.imageUrl);m.put("price",i.product.price);m.put("quantity",i.quantity);return m;}).toList();BigDecimal sum=c.items.stream().map(i->i.product.price.multiply(BigDecimal.valueOf(i.quantity))).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("items",items,"subtotal",sum,"total",sum);}
 @Transactional public Cart add(User u,Long productId,int quantity){Product p=products.findById(productId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));if(quantity<1||quantity>p.stock)throw new ResponseStatusException(HttpStatus.CONFLICT,"Requested quantity exceeds available stock");Cart c=cart(u);CartItem i=c.items.stream().filter(x->x.product.id.equals(p.id)).findFirst().orElse(null);if(i==null){i=new CartItem();i.cart=c;i.product=p;i.quantity=quantity;c.items.add(i);}else{if(i.quantity+quantity>p.stock)throw new ResponseStatusException(HttpStatus.CONFLICT,"Requested quantity exceeds available stock");i.quantity+=quantity;}return carts.save(c);}
 @Transactional public Cart quantity(User u,Long itemId,int q){Cart c=cart(u);CartItem i=c.items.stream().filter(x->x.id.equals(itemId)).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(q<1)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Quantity must be positive");if(q>i.product.stock)throw new ResponseStatusException(HttpStatus.CONFLICT,"Requested quantity exceeds available stock");i.quantity=q;return carts.save(c);}
 @Transactional public Cart remove(User u,Long itemId){Cart c=cart(u);c.items.removeIf(i->i.id.equals(itemId));return carts.save(c);}
 @Transactional public Order place(User u){Cart c=cart(u);if(c.items.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Your cart is empty");Order o=new Order();o.user=u;for(CartItem ci:c.items){if(ci.quantity>ci.product.stock)throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient stock for "+ci.product.name);OrderItem oi=new OrderItem();oi.order=o;oi.productId=ci.product.id;oi.productName=ci.product.name;oi.imageUrl=ci.product.imageUrl;oi.price=ci.product.price;oi.quantity=ci.quantity;o.items.add(oi);o.total=o.total.add(oi.price.multiply(BigDecimal.valueOf(oi.quantity)));ci.product.stock-=ci.quantity;products.save(ci.product);}orders.save(o);c.items.clear();carts.save(c);return o;}
 public Map<String,Object> orderView(Order o){var m=new LinkedHashMap<String,Object>();m.put("id",o.id);m.put("status",o.status);m.put("total",o.total);m.put("createdAt",o.createdAt);m.put("customerName",o.user.name);m.put("items",o.items.stream().map(i->Map.of("productId",i.productId,"productName",i.productName,"imageUrl",Objects.toString(i.imageUrl,""),"price",i.price,"quantity",i.quantity)).toList());return m;}}
